type WikiDescriptionSidecar<TTargetKind extends WikiDescriptionTargetKind = WikiDescriptionTargetKind, TEvidenceRef extends WikiDescriptionEvidenceRef = WikiDescriptionEvidenceRef, TTargetId extends string = string, TMode extends WikiDescriptionExecutionMode = WikiDescriptionExecutionMode> = WikiGeneratedDescriptionSidecar<TTargetKind, TEvidenceRef, TTargetId, TMode> | WikiInsufficientEvidenceSidecar<TTargetKind, TTargetId, TMode>;
type WikiNodeDescriptionSidecar<TEvidenceRef extends WikiDescriptionEvidenceRef = WikiDescriptionEvidenceRef, TTargetId extends string = string, TMode extends WikiDescriptionExecutionMode = WikiDescriptionExecutionMode> = WikiDescriptionSidecar<"node", TEvidenceRef, TTargetId, TMode>;
type WikiCommunityDescriptionSidecar<TEvidenceRef extends WikiDescriptionEvidenceRef = WikiDescriptionEvidenceRef, TTargetId extends string = string, TMode extends WikiDescriptionExecutionMode = WikiDescriptionExecutionMode> = WikiDescriptionSidecar<"community", TEvidenceRef, TTargetId, TMode>;
interface WikiDescriptionSidecarIndex<TNodeId extends string = string, TCommunityId extends string = string> {
    schema: "graphify_wiki_description_index_v1";
    graph_hash: string;
    prompt_version: string;
    nodes: Record<TNodeId, WikiNodeDescriptionSidecar>;
    communities?: Record<TCommunityId, WikiCommunityDescriptionSidecar>;
}
interface CreateInsufficientEvidenceRecordInput<TTargetKind extends WikiDescriptionTargetKind = WikiDescriptionTargetKind, TTargetId extends string = string, TMode extends WikiDescriptionExecutionMode = WikiDescriptionExecutionMode> extends WikiDescriptionCacheKeyInput<TTargetKind, TMode> {
    target_id: TTargetId;
    created_at?: string;
}
declare function buildWikiDescriptionCacheKey(input: WikiDescriptionCacheKeyInput): string;
declare function createInsufficientEvidenceRecord<TTargetKind extends WikiDescriptionTargetKind, TTargetId extends string, TMode extends WikiDescriptionExecutionMode>(input: CreateInsufficientEvidenceRecordInput<TTargetKind, TTargetId, TMode>): WikiInsufficientEvidenceSidecar<TTargetKind, TTargetId, TMode>;
interface WikiDescriptionFreshnessInputs {
    graph_hash: string;
    prompt_version: string;
    mode?: WikiDescriptionExecutionMode | null;
    provider?: string | null;
    model?: string | null;
}
type WikiDescriptionStaleReason = "graph_hash_mismatch" | "prompt_version_mismatch" | "mode_mismatch" | "provider_mismatch" | "model_mismatch" | "cache_key_mismatch";
interface WikiDescriptionFreshnessResult {
    fresh: boolean;
    reasons: WikiDescriptionStaleReason[];
    expected_cache_key: string;
}
/**
 * Decide whether a previously stored sidecar is still valid for the current
 * generation inputs. Any divergence in graph_hash, prompt_version, mode,
 * provider or model invalidates the sidecar so the next render or generation
 * pass treats it as missing.
 */
declare function checkWikiDescriptionFreshness(sidecar: Pick<WikiDescriptionSidecar, "target_id" | "target_kind" | "graph_hash" | "cache_key" | "generator">, inputs: WikiDescriptionFreshnessInputs): WikiDescriptionFreshnessResult;
/**
 * Drop sidecars that are no longer fresh under the current inputs. Designed for
 * render-time use: callers load the on-disk index, call this, and only emit
 * Markdown for the entries that survive.
 */
declare function selectFreshWikiDescriptions<TIndex extends WikiDescriptionSidecarIndex>(index: TIndex, inputs: WikiDescriptionFreshnessInputs): {
    fresh: TIndex;
    stale: {
        nodes: string[];
        communities: string[];
    };
};
declare function validateWikiDescriptionSidecar(value: unknown): string[];

interface OntologyOutputConfig {
    enabled: boolean;
    canonical_node_types?: string[];
    relation_exports?: string[];
    wiki?: {
        enabled?: boolean;
        page_node_types?: string[];
    };
}
interface CompileOntologyOutputsOptions {
    outputDir: string;
    extraction: Extraction;
    profile: NormalizedOntologyProfile;
    config: OntologyOutputConfig;
    /**
     * Optional sidecar index loaded from `.graphify/wiki-descriptions.json`.
     * When provided, ontology entity wiki pages render the validated
     * `generated` description for the canonical entity id. Stale or
     * `insufficient_evidence` sidecars are silently skipped, matching the
     * behaviour of `graphify export wiki --descriptions`. Look-up keys on
     * the canonical `node.id` (not the source graph node ids).
     */
    descriptions?: WikiDescriptionSidecarIndex;
    /**
     * Optional registry records keyed by registry id.  When provided and the
     * profile declares hierarchies, `compileOntologyOutputs` will generate
     * `hierarchies.json` and `hierarchy-index.json` in `outputDir`.
     */
    registries?: Record<string, RegistryRecord[]>;
}
interface CompileOntologyOutputsResult {
    enabled: boolean;
    nodeCount: number;
    relationCount: number;
    wikiPageCount: number;
    validationIssues: string[];
    /** Number of hierarchy arcs written to hierarchies.json (0 when no hierarchies declared). */
    hierarchyArcCount: number;
}
declare function compileOntologyOutputs(options: CompileOntologyOutputsOptions): CompileOntologyOutputsResult;

/**
 * Ontology increment A — profile-declared hierarchy artefacts.
 *
 * Compiles `hierarchies.json` (list of OntologyHierarchyArc) and
 * `hierarchy-index.json` (OntologyHierarchyIndex) from the hierarchy
 * declarations in a NormalizedOntologyProfile.
 *
 * Scope: DECLARATIVE path only (profile → artefact).  The derivation path
 * (reconciliation candidates → hierarchy arcs) is owned by the D1/D2
 * decisions and lives in ontology-reconciliation.ts / ontology-patch.ts —
 * those modules are NOT touched here.
 */

interface CompileHierarchiesOptions {
    /** Normalized hierarchies from the profile (profile.hierarchies). */
    hierarchies: Record<string, NormalizedOntologyHierarchySpec>;
    /** Registry records keyed by registry id, as loaded from disk. */
    registries: Record<string, RegistryRecord[]>;
}
/**
 * Build the flat list of hierarchy arcs from profile-declared hierarchies.
 *
 * For each hierarchy spec, iterates over the bound registry rows and reads
 * `parent_column` / `child_column` from each raw record.  Records that
 * lack either column value are silently skipped (they represent roots or
 * orphaned leaves, which the index will surface via root_ids / depth).
 *
 * IDs used are the registry-native ids exactly as declared — no remapping
 * to canonical ids here (that would be decision D2).
 */
declare function compileHierarchies(options: CompileHierarchiesOptions): OntologyHierarchyArc[];
/**
 * Build the OntologyHierarchyIndex from a flat list of arcs.
 *
 * Cycle detection: Tarjan-style DFS.  Any node whose ancestor path leads
 * back to itself is part of a cycle.  Cycles are reported in `cycles[]` and
 * the nodes involved are excluded from `ancestor_paths` and `root_ids`.
 *
 * Handles disconnected forests (multiple trees / multiple registries).
 */
declare function buildHierarchyIndex(arcs: OntologyHierarchyArc[]): OntologyHierarchyIndex;

