/**
 * Build-time studio scene preprocessor (ÉTAPE 1 — additive, parity-only).
 *
 * `buildStudioScene` is a pure-TypeScript replica of the SPA scene adapter
 * `studio/src/lib/graphAdapter.js` → `buildScene(graph, { showWeakLinks })`.
 * It produces the exact same `{ nodes, edges, stats }` shape and values, so it
 * can be emitted at build time as a light `scene.json` (instead of the SPA
 * reconstructing it client-side from the full 5.8 MB `graph.json`).
 *
 * PARITY CONTRACT (must match graphAdapter.js byte-for-byte in field set and
 * values):
 *   node  -> { id, label, weight, shape, group?, type?, profile metadata?, x/y/fx/fy/fixed? }
 *   edge  -> { source, target, relation?, dash?, profile metadata?, weak? }
 *   stats -> { nodeCount, edgeCount, weakEdgeCount, communityCount }
 *
 * The helpers below are faithful 1:1 ports of the studio helpers
 * (shapeForType/TYPE_SHAPE, dashForRelation/REL_DASH, weightForDegree
 * normalised by maxDegree, computeDegrees, nodeGroup, nodeLabel, nodeType,
 * communityStats for the live community count). Keep them in lockstep with the
 * studio source until ÉTAPE 2 (client wiring) collapses the duplication.
 */
interface StudioSceneGraphNode {
    id: string;
    label?: unknown;
    title?: unknown;
    name?: unknown;
    node_type?: unknown;
    type?: unknown;
    kind?: unknown;
    file_type?: unknown;
    community?: unknown;
    community_name?: unknown;
    [key: string]: unknown;
}
interface StudioSceneGraphEdge {
    source: string;
    target: string;
    relation?: unknown;
    confidence?: unknown;
    [key: string]: unknown;
}
interface StudioSceneGraphLike {
    nodes?: StudioSceneGraphNode[];
    edges?: StudioSceneGraphEdge[];
    links?: StudioSceneGraphEdge[];
}
interface BuildStudioSceneOptions {
    /** Mirror of buildScene's `showWeakLinks` (default true). */
    showWeakLinks?: boolean;
}
interface StudioSceneNode {
    id: string;
    label: string;
    weight: number;
    shape: string;
    group?: string;
    type?: string;
    x?: number;
    y?: number;
    fx?: number;
    fy?: number;
    fixed?: boolean;
    [key: string]: unknown;
}
interface StudioSceneEdge {
    source: string;
    target: string;
    relation?: string;
    relation_type?: string;
    dash?: string;
    weak?: true;
    [key: string]: unknown;
}
interface StudioSceneStats {
    nodeCount: number;
    edgeCount: number;
    weakEdgeCount: number;
    communityCount: number;
}
interface StudioScene {
    nodes: StudioSceneNode[];
    edges: StudioSceneEdge[];
    stats: StudioSceneStats;
}
/**
 * Build the full Studio scene from a GraphLike payload. Strict parity with
 * studio/src/lib/graphAdapter.js → buildScene.
 */
declare function buildStudioScene(graph: StudioSceneGraphLike | null | undefined, options?: BuildStudioSceneOptions): StudioScene;

/**
 * Locate the built SPA directory. Two layouts are supported:
 *   - published package: `dist/studio-app/` (a `prepublish` copy of the Vite
 *     build sits next to the compiled server JS in `dist/`).
 *   - source / dev tree: `studio/dist/` at the repo root (the raw Vite output).
 * Returns null when neither exists (the SPA has not been built yet).
 */
declare function resolveStudioAppDir(): string | null;
interface EntitySidecarResponse {
    id: string;
    description: {
        status: string;
        description: string | null;
    } | null;
    occurrences: unknown;
}
/**
 * Build the `/api/ontology/entity/<id>` payload: the node description
 * (normalised to { status, description }) plus the occurrence record for this
 * node id, if any. Returns the shape the SPA's EntityPanel expects.
 *
 * Description precedence (WP11): the node's own `graph.json` description wins;
 * the opt-in wiki sidecar index is consulted only when the node has none. So a
 * graph whose nodes all carry descriptions reports them all here even without a
 * wiki sidecar present.
 */
declare function buildEntitySidecar(stateDir: string, id: string): EntitySidecarResponse;

/**
 * Deterministic force-directed graph layout (Barnes-Hut, O(n log n)).
 *
 * Pure TypeScript, no DOM. Computes stable (x, y) node positions so they can be
 * PRE-COMPUTED at build time and shipped inside `scene.json`. The studio then
 * pins them (`fx`/`fy`) and renders them directly, turning the former
 * ForceGraph-style ~O(n² × 300) mount simulation (a 1-3 s main-thread freeze on
 * the public pack) into an instant paint.
 *
 * The physics mirror the legacy `ForceGraph` `runSimulation` (same constants and the
 * same FNV/mulberry32 deterministic seed) so pre-computed positions look like
 * what the live component would settle to — but the O(n²) all-pairs repulsion is
 * replaced by a Barnes-Hut quadtree approximation (`theta`). This scales to large
 * graphs and is reused by the runtime Web Worker for on-demand re-layout (P2).
 *
 * Determinism: the seed is an FNV-1a hash over the SORTED node ids (not the
 * count), so adding/removing a node keeps the rest of the layout in place — the
 * same property the Studio relies on after a reconciliation merge.
 */
interface LayoutGraphNode {
    id: string;
    x?: number;
    y?: number;
    /** Pinned x — when both fx and fy are finite the node is held fixed. */
    fx?: number;
    fy?: number;
    [key: string]: unknown;
}
interface LayoutGraphEdge {
    source: string;
    target: string;
    [key: string]: unknown;
}
interface ComputeLayoutOptions {
    /** Number of simulation ticks (default 300, matching the DS default). */
    iterations?: number;
    /** Layout space width — only sets the absolute scale (default 1000). */
    width?: number;
    /** Layout space height (default 1000). */
    height?: number;
    /** Repulsion factor, clamped to [0.1, 10] (default 1). */
    repulsion?: number;
    /** Barnes-Hut opening angle: larger = faster/looser (default 0.9). */
    theta?: number;
}
interface LayoutResult {
    id: string;
    x: number;
    y: number;
}
/**
 * Compute deterministic (x, y) positions for a graph.
 *
 * @returns one `{ id, x, y }` per input node, in input order. Nodes with finite
 *          `fx`/`fy` are held fixed at those coordinates (warm-start / pins).
 */
declare function computeLayout(nodes: readonly {
    id: string;
    fx?: number;
    fy?: number;
}[], edges: readonly {
    source: string;
    target: string;
}[], options?: ComputeLayoutOptions): LayoutResult[];
/**
 * Pre-compute a scene's layout and pin it: writes `x`, `y` AND `fx`, `fy` onto
 * each node so the Studio can render pinned positions directly.
 * Mutates and returns the scene.
 */
declare function attachLayoutPositions<T extends {
    nodes: Array<{
        id: string;
        x?: number;
        y?: number;
        fx?: number;
        fy?: number;
    }>;
    edges: Array<{
        source: string;
        target: string;
    }>;
}>(scene: T, options?: ComputeLayoutOptions): T;

